.sc-tw :root{
            --bg: oklch(8% .02 280);
            --cyan: oklch(79% .17 220);
            --magenta: oklch(70% .28 340);
            --amber: oklch(82% .17 70);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: 'Inter Tight', sans-serif;
            background:
                radial-gradient(circle at 20% 10%, rgba(255, 56, 182, .12), transparent 20%),
                radial-gradient(circle at 80% 20%, rgba(97, 218, 251, .1), transparent 22%),
                linear-gradient(180deg, #09090d 0%, #06060a 100%);
            color: white;
        }.sc-tw body::before{
            content: '';
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px);
            background-size: 100px 100px;
            mask-image: radial-gradient(circle at center, black 20%, transparent 90%);
            opacity: .3;
            z-index: -1;
        }.sc-tw .serif{
            font-family: 'Cormorant Garamond', serif;
            letter-spacing: -.05em;
        }.sc-tw .copy{
            font-family: 'Inter Tight', sans-serif;
        }.sc-tw .glass{
            background: rgba(255, 255, 255, .04);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(30px) saturate(1.4);
            -webkit-backdrop-filter: blur(30px) saturate(1.4);
            box-shadow:
                0 10px 60px rgba(0, 0, 0, .45),
                inset 0 1px 0 rgba(255, 255, 255, .08);
        }.sc-tw .wind{
            animation: wind 8s ease-in-out infinite;
            display: inline-block;
            transform-origin: center bottom;
        }.sc-tw .hero-mask{
            mask-image:
                radial-gradient(circle at center,
                    black 35%,
                    rgba(0, 0, 0, .95) 52%,
                    rgba(0, 0, 0, .75) 70%,
                    transparent 100%);
            -webkit-mask-image:
                radial-gradient(circle at center,
                    black 35%,
                    rgba(0, 0, 0, .95) 52%,
                    rgba(0, 0, 0, .75) 70%,
                    transparent 100%);
        }.sc-tw .hero-video{
            animation: zoom 16s linear infinite alternate;
        }.sc-tw .dock{
            position: fixed;
            bottom: 24px;
            left: 50%;
            transform: translateX(-50%);
            z-index: 60;
        }.sc-tw .dock-inner{
            display: flex;
            gap: 12px;
            padding: 12px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(40px);
            -webkit-backdrop-filter: blur(40px);
        }.sc-tw .dock-btn{
            width: 52px;
            height: 52px;
            border-radius: 999px;
            display: grid;
            place-items: center;
            background: rgba(255, 255, 255, .04);
            transition: .5s cubic-bezier(.16, 1, .3, 1);
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .dock-btn:hover{
            transform: translateY(-6px) scale(1.08);
            background: rgba(255, 255, 255, .08);
        }.sc-tw .floating-label{
            position: absolute;
            padding: 12px 16px;
            border-radius: 999px;
            font-size: 11px;
            letter-spacing: .2em;
            text-transform: uppercase;
            background: rgba(255, 255, 255, .04);
            backdrop-filter: blur(30px);
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .massive-number{
            font-size: clamp(7rem, 20vw, 18rem);
            line-height: .8;
            font-weight: 700;
            color: rgba(255, 255, 255, .06);
        }.sc-tw .river-line{
            height: 1px;
            background:
                linear-gradient(90deg,
                    transparent,
                    rgba(255, 56, 182, .5),
                    rgba(97, 218, 251, .6),
                    transparent);
        }.sc-tw .editorial{
            display: grid;
            grid-template-columns: 1fr 1.2fr;
            gap: 5rem;
            align-items: center;
        }.sc-tw .data-monolith{
            border-radius: 4rem;
            overflow: hidden;
            position: relative;
            min-height: 720px;
            background:
                linear-gradient(145deg,
                    rgba(255, 255, 255, .04),
                    rgba(255, 255, 255, .01));
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .data-monolith::before{
            content: '';
            position: absolute;
            inset: -20%;
            background:
                radial-gradient(circle at 20% 30%, rgba(255, 56, 182, .18), transparent 20%),
                radial-gradient(circle at 80% 40%, rgba(97, 218, 251, .15), transparent 20%),
                radial-gradient(circle at 50% 80%, rgba(255, 153, 0, .12), transparent 25%);
            filter: blur(80px);
        }.sc-tw .orbit{
            position: absolute;
            border: 1px solid rgba(255, 255, 255, .08);
            border-radius: 999px;
        }.sc-tw .marquee{
            display: flex;
            gap: 80px;
            white-space: nowrap;
            animation: marquee 20s linear infinite;
        }.sc-tw .quote-panel{
            padding: 6rem;
            border-radius: 4rem;
            background:
                linear-gradient(180deg,
                    rgba(255, 255, 255, .05),
                    rgba(255, 255, 255, .01));
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .cta-orb{
            width: 14rem;
            height: 14rem;
            border-radius: 999px;
            display: grid;
            place-items: center;
            background:
                radial-gradient(circle at 30% 30%,
                    rgba(255, 255, 255, .18),
                    rgba(255, 255, 255, .04));
            border: 1px solid rgba(255, 255, 255, .1);
            backdrop-filter: blur(30px);
            transition: 1s cubic-bezier(.16, 1, .3, 1);
        }.sc-tw .cta-orb:hover{
            transform: scale(1.08) rotate(8deg);
            box-shadow:
                0 0 100px rgba(97, 218, 251, .18);
        }

        @keyframes marquee {to{
                transform: translateX(-50%);
            }
        }

        @keyframes zoom {from{
                transform: scale(1.05);
            }to{
                transform: scale(1.15);
            }
        }

        @keyframes wind {0%,100%{
                transform: rotate(-1deg);
            }50%{
                transform: rotate(1deg);
            }
